Here is the commit message:
s390/qeth: fix notification for pending buffers during
 teardown

The cited commit reworked the state machine for pending TX buffers.
In qeth_iqd_tx_complete() it turned PENDING into a transient state, and
uses NEED_QAOB for buffers that get parked while waiting for their QAOB
completion.

But it missed to adjust the check in qeth_tx_complete_buf(). So if
qeth_tx_complete_pending_bufs() is called during teardown to drain
the parked TX buffers, we no longer raise a notification for af_iucv.

Instead of updating the checked state, just move this code into
qeth_tx_complete_pending_bufs() itself. This also gets rid of the
special-case in the common TX completion path.

Fixes: 8908f36d20d8 ("s390/qeth: fix af_iucv notification race")
Signed-off-by: Julian Wiedmann <jwi@linux.ibm.com>
Signed-off-by: David S. Miller <davem@davemloft.net>

Here is the root cause:
The bug was caused by the failure to properly notify the system about the state of pending TX buffers during the teardown process. The state machine for pending TX buffers was reworked, but the check for the `PENDING` state in the `qeth_tx_complete_buf()` function was not updated accordingly. As a result, when `qeth_tx_complete_pending_bufs()` was called to drain parked TX buffers, it did not raise the necessary notification for `af_iucv`, leading to a race condition.

Here is the patch:

 static void qeth_tx_complete_buf(struct qeth_qdio_out_buffer *buf, bool error,
 				 int budget)
 {
 	struct qeth_qdio_out_q *queue = buf->q;
 	struct sk_buff *skb;

-	if (atomic_read(&buf->state) == QETH_QDIO_BUF_PENDING)
-		qeth_notify_skbs(queue, buf, TX_NOTIFY_GENERALERROR);
-
 	/* Empty buffer? */
 	if (buf->next_element_to_fill == 0)
 		return;

 	QETH_TXQ_STAT_INC(queue, bufs);
 	QETH_TXQ_STAT_ADD(queue, buf_elements, buf->next_element_to_fill);
 	if (error) {
 		QETH_TXQ_STAT_ADD(queue, tx_errors, buf->frames);
 	} else {
 		QETH_TXQ_STAT_ADD(queue, tx_packets, buf->frames);
 		QETH_TXQ_STAT_ADD(queue, tx_bytes, buf->bytes);
 	}

 	while ((skb = __skb_dequeue(&buf->skb_list)) != NULL) {
 		unsigned int bytes = qdisc_pkt_len(skb);
 		bool is_tso = skb_is_gso(skb);
 		unsigned int packets;

 		packets = is_tso ? skb_shinfo(skb)->gso_segs : 1;
 		if (!error) {
 			if (skb->ip_summed == CHECKSUM_PARTIAL)
 				QETH_TXQ_STAT_ADD(queue, skbs_csum, packets);
 			if (skb_is_nonlinear(skb))
 				QETH_TXQ_STAT_INC(queue, skbs_sg);
 			if (is_tso) {
 				QETH_TXQ_STAT_INC(queue, skbs_tso);
 				QETH_TXQ_STAT_ADD(queue, tso_bytes, bytes);
 			}
 		}

 		napi_consume_skb(skb, budget);
 	}
 }


 static void qeth_tx_complete_pending_bufs(struct qeth_card *card,
 					  struct qeth_qdio_out_q *queue,
 					  bool drain)
 {
 	struct qeth_qdio_out_buffer *buf, *tmp;

 	list_for_each_entry_safe(buf, tmp, &queue->pending_bufs, list_entry) {
 		if (drain || atomic_read(&buf->state) == QETH_QDIO_BUF_EMPTY) {
 			QETH_CARD_TEXT(card, 5, "fp");
 			QETH_CARD_TEXT_(card, 5, "%lx", (long) buf);

+			if (drain)
+				qeth_notify_skbs(queue, buf,
+						 TX_NOTIFY_GENERALERROR);
 			qeth_tx_complete_buf(buf, drain, 0);

 			list_del(&buf->list_entry);
 			kmem_cache_free(qeth_qdio_outbuf_cache, buf);
 		}
 	}
 }



